const subSize=W*(portrait?.038:.018);ctx.font='400 '+subSize+'px system-ui';const words=scene.text.split(/\s+/),pages=Math.max(1,Math.ceil(words.length/(portrait?18:30)));const page=Math.min(pages-1,Math.floor(local/scene.duration*pages));const per=Math.ceil(words.length/pages),sub=words.slice(page*per,(page+1)*per).join(' ');textBlock(ctx,sub,margin,H*.84,W*.88,subSize,p.text,portrait?5:3);ctx.globalAlpha=1;ctx.fillStyle=p.muted;ctx.font='500 '+Math.max(9,W*.008)+'px system-ui';ctx.textAlign='right';ctx.fillText(String(i+1).padStart(2,'0')+' / '+String(state.scenes.length).padStart(2,'0'),W-margin,H*.06);ctx.textAlign='left';ctx.fillText('M1LASH · '+(state.lang==='ru'?'РУССКИЙ':'ENGLISH'),margin,H*.06);
