async function audioCtx(){if(!audioContext)audioContext=new AudioContext();if(audioContext.state==='suspended')await audioContext.resume();return audioContext;}
function stopSources(){for(const s of [voiceSource,musicSource])try{s?.stop();}catch{}voiceSource=musicSource=null;}
async function startAudio(offset,dest){const ac=await audioCtx();stopSources();if(voiceBuffer&&offset<voiceBuffer.duration){voiceSource=ac.createBufferSource();voiceSource.buffer=voiceBuffer;voiceSource.connect(ac.destination);if(dest)voiceSource.connect(dest);voiceSource.start(0,offset);}if(musicBuffer){musicSource=ac.createBufferSource();musicSource.buffer=musicBuffer;musicSource.loop=true;const gain=ac.createGain();gain.gain.value=state.musicVolume;musicSource.connect(gain);gain.connect(ac.destination);if(dest)gain.connect(dest);musicSource.start(0,offset%musicBuffer.duration);}}
function stopPlayback(){playing=false;stopSources();$('play').textContent='▶';if(window.speechSynthesis)speechSynthesis.cancel();}
function tick(ts){if(playing){if(lastTick)current+=(ts-lastTick)/1000;if(current>=total()){current=total();stopPlayback();if(recording&&recorder?.state==='recording')recorder.stop();}draw(current);updateClock();}lastTick=ts;requestAnimationFrame(tick);}
$('play').onclick=async()=>{if(recording)return;if(playing){stopPlayback();return;}if(current>=total())current=0;try{await startAudio(current);playing=true;lastTick=0;$('play').textContent='Ⅱ';}catch(e){toast('Не удалось включить звук: '+e.message);}};
$('scrub').oninput=()=>{if(recording)return;stopPlayback();current=+$('scrub').value;draw(current);updateClock();};
function view(name){if(recording)return;document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!=='view-'+name);document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('pageName').textContent=({studio:'Студия',projects:'Мои проекты',trends:'Радар трендов',channels:'Каналы и автопилот',guide:'Как это работает',settings:'Подключения'})[name];if(name==='projects')projectList();if(name==='trends')loadTrends();if(name==='channels')loadAutomation();}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>view(b.dataset.go));
for(const [id,key] of [['title','title'],['topic','topic'],['duration','target'],['lang','lang'],['theme','theme'],['resolution','resolution'],['stylePreset','stylePreset'],['referenceUrl','referenceUrl']])$(id).oninput=()=>{if(recording)return;state[key]=['target','resolution'].includes(key)?+$(id).value:$(id).value;if(key==='resolution')resizeCanvas();changed();draw(current);};
for(const [id,key] of [['sceneTitle','title'],['sceneText','text'],['sceneDuration','duration'],['sceneCountry','country'],['sceneType','type'],['sceneSource','source'],['verified','verified'],['sceneItems','items']])$(id).oninput=()=>{if(recording)return;const s=state.scenes[selected];s[key]=key==='items'?$(id).value.split('|').map(s=>s.trim()).filter(Boolean).slice(0,5):key==='duration'?Math.max(2,Math.min(180,+$(id).value||2)):key==='verified'?$(id).checked:$(id).value;if(['text','source','title','country'].includes(key)){s.verified=false;$('verified').checked=false;}current=Math.min(current,total());changed();draw(current);};
