document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{if(recording)return;state.format=b.dataset.format;renderUI();changed();});
$('addScene').onclick=()=>{if(recording)return;stopPlayback();state.scenes.push({title:'Новая сцена',text:'Добавь текст диктора.',country:'',duration:8,type:'title',source:'',verified:false});selected=state.scenes.length-1;current=startOf(selected);renderUI();changed();};
